// Rules:
// - Optional leading "export " is ignored before key parsing.
// - [profile] starts a profile; keys become "profile.KEY".
// - Lines ending in backslash continue; continuation leading whitespace is trimmed.
// - '#' starts a comment only outside double quotes.
// - First '=' separates key and value; quoted values are unquoted.
std::map<std::string, std::string> parse_env_file(const std::string& text) {

