// RFC 4648 Base32 alphabet
const std::string STANDARD_B32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

// Reversed alphabet — default
const std::string REVERSED_B32 = "765432ZYXWVUTSRQPONMLKJIHGFEDCBA";

// Count leading zero bytes
int count_leading_zeros(const std::vector<uint8_t>& data) {
    int c = 0;
    for (auto b : data) { if (b) break; c++; }
    return c;
}

// Base32 encode using INTEGER DIVISION (like base58), NOT 5-bit grouping.
// Repeatedly divmod by 32 to extract digits.
// Leading zero bytes map to alphabet[0].
// Default alphabet is REVERSED_B32.
std::string base32_encode(const std::vector<uint8_t>& data,
                          const std::string& alphabet = REVERSED_B32) {

