    done = true; int rem = 0;
    for (size_t i = 0; i < buf.size(); i++) { if (buf[i]) done = false; int acc = rem * 256 + buf[i]; buf[i] = acc / 32; rem = acc % 32; }
    if (!done) result = alphabet[rem] + result;
}
