// Strip # comments from each line, but NOT inside double or single quotes.
// Backslash escapes inside quotes: \" and \' don't end the string.
// Returns the result with trailing whitespace on each line preserved
// (only the comment portion is removed).
std::string strip_comments(const std::string& text) {

