    for (size_t i = 0; i < line.size(); i++) {
        char c = line[i];
        if (q) { if (c=='\\' && i+1<line.size()) { result+=c; result+=line[++i]; continue; } if (c==q) q=0; result+=c; }
        else { if (c=='#') break; if (c=='"'||c=='\'') q=c; result+=c; }
