#include <string>
#include <stack>
#include <cassert>

// Check if brackets are balanced in the input string.
// Brackets: ( ) [ ] { }
// Ignore brackets inside double-quoted strings "...".
// Backslash escapes inside strings: \" does not end the string.
// Returns true if balanced, false otherwise.
bool brackets_balanced(const std::string& text) {

golden_completion:
std::stack<char> stk; bool in_str = false;
for (size_t i = 0; i < text.size(); i++) {
    char c = text[i];
    if (in_str) { if (c=='\\' && i+1<text.size()) { i++; continue; } if (c=='"') in_str=false; continue; }
    if (c == '"') { in_str = true; continue; }
    if (c=='('||c=='['||c=='{') stk.push(c);
    else if (c==')'||c==']'||c=='}') {
        if (stk.empty()) return false; char t=stk.top(); stk.pop();
        if ((c==')'&&t!='(')||(c==']'&&t!='[')||(c=='}'&&t!='{')) return false;
    }
} return stk.empty();

suffix:
}

int main() {
    assert(brackets_balanced("()[]{}") == true);
    assert(brackets_balanced("([)]") == false);
    assert(brackets_balanced("(]") == false);

    // Brackets inside strings should be IGNORED
    assert(brackets_balanced("\"(\"") == true);
    assert(brackets_balanced("\"[[[\"") == true);

    // Escaped quote inside string: the bracket after \" is still inside the string
    assert(brackets_balanced("\"hello \\\" ( world\"") == true);

    return 0;
}

