assert(brackets_balanced("abc") == true);
assert(brackets_balanced("(") == false);
assert(brackets_balanced(")") == false);
// Mixed brackets and strings
assert(brackets_balanced("{\"}\"}") == true);
assert(brackets_balanced("[\"]\"]") == true);
// Nested correctly
assert(brackets_balanced("({[]})") == true);
// Backslash outside string is not special — ( and ) still match
assert(brackets_balanced("(\\)") == true);
// Mismatched outside strings
assert(brackets_balanced("(}") == false);
// Unclosed string with bracket — string is unclosed, bracket inside
// Actually, we treat unclosed string as still in_str, so bracket is ignored => balanced stack
assert(brackets_balanced("\"(") == true);

