// Custom edit distance: insert=1, delete=1, replace=1, but
// swapping two ADJACENT characters costs 0.5 (Damerau transposition).
// edit_distance("ab", "ba") = 0.5, NOT 2.
// edit_distance("cat", "car") = 1.0 (replace, no swap possible).
