// Run-length encode a string.
// Output format: COUNT then CHARACTER, e.g. "aaabbc" => "3a2b1c".
// Single occurrences still get "1" prefix: "abc" => "1a1b1c".
// Empty input returns empty string.
// This is count-BEFORE-char format, NOT the common char-then-count format.
std::string run_length_encode(const std::string& s) {

golden_completion:
if (s.empty()) return "";
std::string result;
int count = 1;
for (size_t i = 1; i <= s.size(); i++) {
    if (i < s.size() && s[i] == s[i-1]) {
        count++;
    } else {
        result += std::to_string(count) + s[i-1];
        count = 1;
    }
}
return result;

suffix:
}

