// Custom sort: primary key = length (ascending), secondary key = reverse
// alphabetical (descending) for same-length strings.
// "cat" < "apple" because len 3 < len 5.
// "cat" > "ant" because same length 3 but 'c' > 'a' (reverse alpha: c first).
// So among length-3 strings: "cat", "bat", "ant" => sorted as "cat", "bat", "ant".
std::vector<std::string> custom_sort(std::vector<std::string> items) {

golden_completion:
std::sort(items.begin(), items.end(), [](const std::string& a, const std::string& b) {
    if (a.size() != b.size()) return a.size() < b.size();
    return a > b;  // reverse alphabetical
});
return items;

suffix:
}

int main() {
    auto r1 = custom_sort({"apple", "cat", "bat", "ant", "be"});
    assert(r1 == (std::vector<std::string>{"be", "cat", "bat", "ant", "apple"}));

    // Same length, reverse alpha
    auto r2 = custom_sort({"c", "a", "b"});
    assert(r2 == (std::vector<std::string>{"c", "b", "a"}));

    // Already sorted
