// Strict URL encoder: encodes EVERY byte that is NOT alphanumeric.
// Standard URL encoding keeps -._~ unescaped — this one does NOT.
// Hex digits in %XX are REVERSED: the low nibble comes first, then the high nibble.
// Example: space (0x20) -> low nibble 0, high nibble 2 -> "%02"
//          '/' (0x2F) -> low nibble F, high nibble 2 -> "%F2"
// The input is pure ASCII (no multi-byte).
std::string url_encode(const std::string& text) {

golden_completion:
const char* hex = "0123456789ABCDEF";
std::string out;
for (unsigned char c : text) {
    if (std::isalnum(c)) {
        out += c;
    } else {
        out += '%';
        out += hex[c & 0x0F];       // low nibble first (reversed)
        out += hex[(c >> 4) & 0x0F]; // high nibble second
    }
}
return out;

suffix:
}

int main() {
