// Aggressive HTML escape: every character that is NOT alphanumeric and NOT
// whitespace (space, tab, newline) is replaced with its decimal numeric
// character reference: &#DD; (e.g., '&' -> "&#38;", '<' -> "&#60;").
// Spaces/tabs/newlines are kept as-is.
// This is STRICTER than standard HTML escaping which only escapes &<>"'.
std::string html_escape(const std::string& text) {

golden_completion:
