for (unsigned char c : text) {
    if (std::isalnum(c) || c == ' ' || c == '\t' || c == '\n') {
        out += c;
    } else {
        out += "&#";
        out += std::to_string(static_cast<int>(c));
        out += ";";
    }
}
return out;

suffix:
}

