struct LogEntry {
    std::string timestamp;  // e.g., "2024-01-15 10:30:45"
    std::string level;      // INFO, WARN, ERROR, DEBUG
    std::string message;    // rest of the line after the level
};

// Parse log lines in format: "[TIMESTAMP] LEVEL: message text"
// Example: "[2024-01-15 10:30:45] ERROR: disk full"
// The timestamp is everything between '[' and ']'.
// The level is the first word after '] ', ending at ':'.
// The message is everything after ": " (note: space after colon).
// If a line doesn't match this format, skip it.
std::vector<LogEntry> parse_log(const std::string& text) {

golden_completion:
std::vector<LogEntry> entries; size_t pos = 0;
while (pos < text.size()) {
    size_t eol = text.find('\n', pos); if (eol==std::string::npos) eol=text.size();
    std::string line = text.substr(pos, eol-pos); pos = eol+1;
    if (line.empty()||line[0]!='[') continue;
    size_t cb=line.find(']',1); if (cb==std::string::npos) continue;
    size_t colon=line.find(':',cb+2); if (colon==std::string::npos) continue;
    entries.push_back({line.substr(1,cb-1), line.substr(cb+2,colon-cb-2), colon+2<line.size()?line.substr(colon+2):""});
}
return entries;

