enum class TokenType { NUMBER, STRING, IDENT, OP, LPAREN, RPAREN, END };

struct Token {
    TokenType type;
    std::string value;
    bool operator==(const Token& o) const { return type == o.type && value == o.value; }
};

// Tokenize an expression string.  Token types:
// - NUMBER: sequence of digits (no decimals)
// - STRING: characters between double quotes (the quotes are NOT included in value;
//   backslash-escaped quotes \" inside strings are literal quotes)
// - IDENT: letter followed by letters/digits/underscores
// - OP: one of the multi-char operators ==, !=, <=, >=, &&, ||
//       OR a single-char operator: +, -, *, /, <, >, =, !, &, |
//       Multi-char operators take priority over single-char.
// - LPAREN: '('   RPAREN: ')'
// Whitespace is skipped.  Unknown characters are skipped.
std::vector<Token> tokenize(const std::string& expr) {

