while (i<expr.size()) {
    char c=expr[i]; if(std::isspace(c)){i++;continue;}
    if(std::isdigit(c)){size_t s=i;while(i<expr.size()&&std::isdigit(expr[i]))i++;tokens.push_back({TokenType::NUMBER,expr.substr(s,i-s)});continue;}
    if(c=='"'){i++;std::string v;while(i<expr.size()&&expr[i]!='"'){if(expr[i]=='\\'&&i+1<expr.size())v+=expr[++i];else v+=expr[i];i++;}if(i<expr.size())i++;tokens.push_back({TokenType::STRING,v});continue;}
