    auto t = tokenize("x == 10 && y != 20");
    assert(t.size() == 7);
    assert(t[0] == (Token{TokenType::IDENT, "x"}));
    assert(t[1] == (Token{TokenType::OP, "=="}));
    assert(t[2] == (Token{TokenType::NUMBER, "10"}));
    assert(t[3] == (Token{TokenType::OP, "&&"}));
    assert(t[4] == (Token{TokenType::IDENT, "y"}));
    assert(t[5] == (Token{TokenType::OP, "!="}));
