struct Node {
    int value = 0;
    bool is_leaf = true;
    std::vector<Node> children;
    Node(int v) : value(v), is_leaf(true) {}
    Node(std::vector<Node> c) : is_leaf(false), children(std::move(c)) {}
};

// deep_flatten: flatten a tree of Nodes into a vector of ints.
// - depth=0: return top-level leaf values only (skip non-leaf children).
// - depth=1: flatten one level; at the boundary, non-leaf nodes are SKIPPED.
// - depth=-1: fully recursive flatten (all leaves at any depth).
std::vector<int> deepFlatten(const Node& root, int depth) {

golden_completion:
std::vector<int> result;
if (root.is_leaf) { result.push_back(root.value); return result; }
for (const auto& child : root.children) {
    if (child.is_leaf) { result.push_back(child.value); }
    else if (depth == -1) { auto sub = deepFlatten(child, -1); result.insert(result.end(), sub.begin(), sub.end()); }
    else if (depth > 0) { auto sub = deepFlatten(child, depth - 1); result.insert(result.end(), sub.begin(), sub.end()); }
}
return result;

