    // Tree: [1, [2, [3, 4]], 5]
    Node tree({Node(1), Node({Node(2), Node({Node(3), Node(4)})}), Node(5)});

    auto r0 = deepFlatten(tree, 0);
    assert(r0 == std::vector<int>({1, 5}));  // only top-level leaves

    auto r1 = deepFlatten(tree, 1);
    assert(r1 == std::vector<int>({1, 2, 5}));  // one level: 2 is leaf of child, [3,4] skipped

    auto rf = deepFlatten(tree, -1);
    assert(rf == std::vector<int>({1, 2, 3, 4, 5}));  // full flatten
