// zip_extend: Zip two vectors together. When one is shorter,
// extend it by repeating its LAST element (not a default/zero value).
// If either vector is empty, return empty.
// Returns vector of pairs with length == max(a.size(), b.size()).
template<typename T>
std::vector<std::pair<T, T>> zipExtend(
    const std::vector<T>& a, const std::vector<T>& b) {

golden_completion:
if (a.empty() || b.empty()) return {};
std::vector<std::pair<T, T>> result;
size_t len = std::max(a.size(), b.size());
for (size_t i = 0; i < len; i++) {
    T va = (i < a.size()) ? a[i] : a.back();
    T vb = (i < b.size()) ? b[i] : b.back();
    result.push_back({va, vb});
}
return result;

