// uniqueSorted: Sort the input AND remove duplicates.
// "Duplicate" defined by eq function. Sort order by less function.
// When duplicates found, keep the FIRST occurrence from ORIGINAL order.
// Returns sorted vector with no equivalent-duplicates.
template<typename T>
std::vector<T> uniqueSorted(
    const std::vector<T>& data,
    std::function<bool(const T&, const T&)> less,
    std::function<bool(const T&, const T&)> eq) {

golden_completion:
