std::vector<std::string> weighted_random_select(const std::vector<std::string>& items, const std::vector<double>& weights, int n, LCG& rng) {
    assert(items.size() == weights.size());
    double total_weight = std::accumulate(weights.begin(), weights.end(), 0.0);
    std::vector<double> cumulative_weights(weights.size());
    cumulative_weights[0] = weights[0];
    for (size_t i = 1; i < weights.size(); ++i) {
        cumulative_weights[i] = cumulative_weights[i-1] + weights[i];
    }
    std::vector<std::string> selected(n);
    for (int i = 0; i < n; ++i) {
        double r = rng.next() * total_weight;
        auto it = std::lower_bound(cumulative_weights.begin(), cumulative_weights.end(), r);
        selected[i] = items[std::distance(cumulative_weights.begin(), it)];
    }
    return selected;
}

